@Test
public void testAnalyze() {
    // case 1
    LikePredicate likePredicate = new LikePredicate(org.apache.doris.analysis.LikePredicate.Operator.LIKE, new SlotRef(null, "k1"), new StringLiteral("abc"));
    DeleteStmt deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), "partition", likePredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        Assert.assertTrue(e.getMessage().contains("should be compound or binary predicate"));
    }
    // case 2
    BinaryPredicate binaryPredicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new StringLiteral("abc"));
    CompoundPredicate compoundPredicate = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.OR, binaryPredicate, binaryPredicate);
    deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), "partition", compoundPredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        Assert.assertTrue(e.getMessage().contains("should be AND"));
    }
    // case 3
    compoundPredicate = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.AND, binaryPredicate, likePredicate);
    deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), "partition", compoundPredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        Assert.assertTrue(e.getMessage().contains("should be compound or binary predicate"));
    }
    // case 4
    binaryPredicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new SlotRef(null, "k1"));
    compoundPredicate = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.AND, binaryPredicate, binaryPredicate);
    deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), "partition", compoundPredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        Assert.assertTrue(e.getMessage().contains("Right expr should be value"));
    }
    // case 5
    binaryPredicate = new BinaryPredicate(Operator.EQ, new StringLiteral("abc"), new SlotRef(null, "k1"));
    compoundPredicate = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.AND, binaryPredicate, binaryPredicate);
    deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), "partition", compoundPredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        Assert.assertTrue(e.getMessage().contains("Left expr should be column name"));
    }
    // case 6 partition is null
    binaryPredicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new StringLiteral("abc"));
    compoundPredicate = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.AND, binaryPredicate, binaryPredicate);
    deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), null, compoundPredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.assertTrue(e.getMessage().contains("Partition is not set"));
    }
    // normal
    binaryPredicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new StringLiteral("abc"));
    CompoundPredicate compoundPredicate2 = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.AND, binaryPredicate, binaryPredicate);
    compoundPredicate = new CompoundPredicate(org.apache.doris.analysis.CompoundPredicate.Operator.AND, binaryPredicate, compoundPredicate2);
    deleteStmt = new DeleteStmt(new TableName("testDb", "testTbl"), "partition", compoundPredicate);
    try {
        deleteStmt.analyze(analyzer);
    } catch (UserException e) {
        Assert.fail();
    }
}

