    }
    // cancel restore
    try {
        handler.cancel(new CancelBackupStmt(CatalogMocker.TEST_DB_NAME, true));
    } catch (DdlException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // drop repo
    try {
        handler.dropRepository(new DropRepositoryStmt("repo"));
    } catch (DdlException e) {
        e.printStackTrace();
        Assert.fail();
    }
}

