    Method runQuorumFinishedJobs = UnitTestUtil.getPrivateMethod(LoadChecker.class, "runQuorumFinishedJobs", new Class[] {});
    runQuorumFinishedJobs.invoke(checkers.get(JobState.QUORUM_FINISHED), new Object[] {});
