    Assert.assertTrue(auth.checkDbPriv("172.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db", SystemInfoService.DEFAULT_CLUSTER + ":cmy", PrivPredicate.DROP));
    // 19. revoke tbl privs from user @ ip
    tablePattern = new TablePattern("db2", "tbl2");
    privileges = Lists.newArrayList(AccessPrivilege.ALTER_PRIV);
    revokeStmt = new RevokeStmt(new UserIdentity("zhangsan", "192.%"), null, tablePattern, privileges);
    try {
        revokeStmt.analyze(analyzer);
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(auth.checkTblPriv("192.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db2", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", "tbl2", PrivPredicate.ALTER));
    try {
        auth.revoke(revokeStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(auth.checkTblPriv("192.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db2", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", "tbl2", PrivPredicate.ALTER));
    Assert.assertTrue(auth.checkDbPriv("192.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db1", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", PrivPredicate.SELECT));
    // 20. revoke privs from non exist user @ domain
    tablePattern = new TablePattern("db2", "tbl2");
    privileges = Lists.newArrayList(AccessPrivilege.ALTER_PRIV);
    revokeStmt = new RevokeStmt(new UserIdentity("zhangsan", "nodomain", true), null, tablePattern, privileges);
    try {
        revokeStmt.analyze(analyzer);
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
    hasException = false;
    try {
        auth.revoke(revokeStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        hasException = true;
    }
    Assert.assertTrue(hasException);
    // 21. revoke privs from non exist db from user @ domain
    tablePattern = new TablePattern("nodb", "*");
    privileges = Lists.newArrayList(AccessPrivilege.ALTER_PRIV);
    revokeStmt = new RevokeStmt(new UserIdentity("zhangsan", "palo.domain1", true), null, tablePattern, privileges);
    try {
        revokeStmt.analyze(analyzer);
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
    hasException = false;
    try {
        auth.revoke(revokeStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        hasException = true;
    }
    Assert.assertTrue(hasException);
    // 22. revoke privs from exist user @ domain
    tablePattern = new TablePattern("db3", "*");
    privileges = Lists.newArrayList(AccessPrivilege.DROP_PRIV);
    revokeStmt = new RevokeStmt(new UserIdentity("zhangsan", "palo.domain1", true), null, tablePattern, privileges);
    try {
        revokeStmt.analyze(analyzer);
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(auth.checkDbPriv("10.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db3", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", PrivPredicate.DROP));
    try {
        auth.revoke(revokeStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(auth.checkDbPriv("10.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db3", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", PrivPredicate.DROP));
    resolver.runOneCycle();
    Assert.assertFalse(auth.checkDbPriv("10.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db3", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", PrivPredicate.DROP));
    Assert.assertFalse(auth.checkDbPriv("10.1.1.3", SystemInfoService.DEFAULT_CLUSTER + ":db3", SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", PrivPredicate.DROP));
    /*
         * for now, we have following auth:
         * cmy@'%'
         *      *.* -> DROP
         * zhangsan@"192.%"
         *      db1.* -> SELECT/DROP
         *      db2.tbl2 -> DROP
         * zhangsan@['palo.domain1']
         *      db3.* -> ALTER/SELECT
         * lisi@['palo.domain2']
         *      N/A
         */
    // 23. create admin role, which is not allowed
    CreateRoleStmt roleStmt = new CreateRoleStmt(PaloRole.ADMIN_ROLE);
    hasException = false;
    try {
        roleStmt.analyze(analyzer);
    } catch (UserException e1) {
        e1.printStackTrace();
        hasException = true;
    }
    Assert.assertTrue(hasException);
    // 23. create operator role, which is not allowed
    roleStmt = new CreateRoleStmt(PaloRole.OPERATOR_ROLE);
    hasException = false;
    try {
        roleStmt.analyze(analyzer);
    } catch (UserException e1) {
        e1.printStackTrace();
        hasException = true;
    }
    Assert.assertTrue(hasException);
    // 24. create role
    roleStmt = new CreateRoleStmt("rolo1");
    try {
        roleStmt.analyze(analyzer);
    } catch (UserException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    try {
        auth.createRole(roleStmt);
    } catch (DdlException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // 25. grant auth to non exist role, will create this new role
    privileges = Lists.newArrayList(AccessPrivilege.DROP_PRIV, AccessPrivilege.SELECT_PRIV);
    grantStmt = new GrantStmt(null, "role2", new TablePattern("*", "*"), privileges);
    try {
        grantStmt.analyze(analyzer);
    } catch (UserException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    try {
        auth.grant(grantStmt);
    } catch (DdlException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // 26. grant auth to role
    privileges = Lists.newArrayList(AccessPrivilege.DROP_PRIV, AccessPrivilege.SELECT_PRIV);
    grantStmt = new GrantStmt(null, "role1", new TablePattern("*", "*"), privileges);
    try {
        grantStmt.analyze(analyzer);
    } catch (UserException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    try {
        auth.grant(grantStmt);
    } catch (DdlException e1) {
        e1.printStackTrace();
        Assert.fail();
    }
    // 27. create user and set it as role1
    userIdentity = new UserIdentity("wangwu", "%");
    userDesc = new UserDesc(userIdentity, "12345", true);
    userStmt = new CreateUserStmt(false, userDesc, "role1");
    try {
        userStmt.analyze(analyzer);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(auth.checkDbPriv("10.17.2.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":wangwu", PrivPredicate.DROP));
    try {
        auth.createUser(userStmt);
    } catch (DdlException e) {
        Assert.fail();
    }
    Assert.assertTrue(auth.checkDbPriv("10.17.2.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":wangwu", PrivPredicate.DROP));
    // 28. create user@domain and set it as role1
    userIdentity = new UserIdentity("chenliu", "palo.domain2", true);
    userDesc = new UserDesc(userIdentity, "12345", true);
    userStmt = new CreateUserStmt(false, userDesc, "role1");
    try {
        userStmt.analyze(analyzer);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    try {
        auth.createUser(userStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(auth.checkDbPriv("20.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":chenliu", PrivPredicate.DROP));
    resolver.runOneCycle();
    Assert.assertTrue(auth.checkDbPriv("20.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":chenliu", PrivPredicate.DROP));
    // 29. revoke auth on non exist db from role1
    privileges = Lists.newArrayList(AccessPrivilege.DROP_PRIV);
    revokeStmt = new RevokeStmt(null, "role1", new TablePattern("nodb", "*"), privileges);
    try {
        revokeStmt.analyze(analyzer);
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
    hasException = false;
    try {
        auth.revoke(revokeStmt);
    } catch (DdlException e1) {
        e1.printStackTrace();
        hasException = true;
    }
    Assert.assertTrue(hasException);
    // 30. revoke auth from role1
    privileges = Lists.newArrayList(AccessPrivilege.DROP_PRIV);
    revokeStmt = new RevokeStmt(null, "role1", new TablePattern("*", "*"), privileges);
    try {
        revokeStmt.analyze(analyzer);
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
    try {
        auth.revoke(revokeStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertTrue(auth.checkDbPriv("20.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":chenliu", PrivPredicate.DROP));
    resolver.runOneCycle();
    Assert.assertFalse(auth.checkDbPriv("20.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":chenliu", PrivPredicate.DROP));
    // 31. drop role, privs remain unchanged
    DropRoleStmt dropRoleStmt = new DropRoleStmt("role1");
    try {
        dropRoleStmt.analyze(analyzer);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    try {
        auth.dropRole(dropRoleStmt);
    } catch (DdlException e) {
        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(auth.checkDbPriv("20.1.1.1", SystemInfoService.DEFAULT_CLUSTER + ":db4", SystemInfoService.DEFAULT_CLUSTER + ":chenliu", PrivPredicate.DROP));
    // drop user cmy
    DropUserStmt dropUserStmt = new DropUserStmt(new UserIdentity("cmy", "%"));
    try {
        dropUserStmt.analyze(analyzer);
    } catch (UserException e) {
        e.printStackTrace();
        Assert.fail();
    }
    try {
        auth.dropUser(dropUserStmt);
    } catch (DdlException e) {
        Assert.fail();
    }
    Assert.assertFalse(auth.checkPlainPassword(SystemInfoService.DEFAULT_CLUSTER + ":cmy", "192.168.0.1", "12345"));
    Assert.assertTrue(auth.checkPlainPassword(SystemInfoService.DEFAULT_CLUSTER + ":zhangsan", "192.168.0.1", "12345"));
}

@Test
public void testGlobalPriv() throws DdlException, IllegalAccessException, IllegalArgumentException, InvocationTargetException {
    // exact match
    grantGlobalPrivs("192.168.1.1", "cmy", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.GRANT_PRIV));
    Assert.assertFalse(auth.checkGlobalPriv("192.168.1.2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("192.168.1.1", "cmy2", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("192.168.1.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.NODE_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("192.168.1.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    // fuzzy match
    auth.clear();
    grantGlobalPrivs("192.168._.%", "cmy\\_%", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.GRANT_PRIV, PaloPrivilege.NODE_PRIV));
    Assert.assertFalse(auth.checkGlobalPriv("192.168.1.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("192.168.1.200", "cmy_123", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("192.168.1.200", "cmy_123", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV, PaloPrivilege.NODE_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("192.168.1.200", "cmy_", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.NODE_PRIV), Operator.OR)));
    auth.clear();
    grantGlobalPrivs("192.168.%", ".cmy", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.GRANT_PRIV));
    Assert.assertFalse(auth.checkGlobalPriv("192.10.1.1", ".cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("192.168.1.200", ".cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    // multi priv entries
    auth.clear();
    grantGlobalPrivs("%", "cmy", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.GRANT_PRIV));
    grantGlobalPrivs("localhost", "cmy", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.NODE_PRIV));
    grantGlobalPrivs("127.0.0.1", "cmy", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.SELECT_PRIV));
    Assert.assertTrue(auth.checkGlobalPriv("127.0.0.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("127.0.0.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("localhost", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.NODE_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("localhost", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("192.168.1.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    // test persist
    auth = testPersist(auth);
    Assert.assertTrue(auth.checkGlobalPriv("127.0.0.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("127.0.0.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("localhost", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.NODE_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkGlobalPriv("localhost", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkGlobalPriv("192.168.1.1", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.GRANT_PRIV), Operator.OR)));
}

@Test
public void testDbPriv() throws DdlException, IllegalAccessException, IllegalArgumentException, InvocationTargetException {
    // normal
    grantDbPrivs("192.168.1.%", "my\\_database", "cmy", false, false, false, PrivBitSet.of(PaloPrivilege.SELECT_PRIV, PaloPrivilege.ALTER_PRIV));
    Assert.assertTrue(auth.checkDbPriv("192.168.1.1", "my_database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkDbPriv("192.168.1.1", "my_database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV, PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.1.2", "my_database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV, PaloPrivilege.LOAD_PRIV), Operator.AND)));
    Assert.assertTrue(auth.checkDbPriv("192.168.1.2", "my_database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV, PaloPrivilege.LOAD_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.1.1", "my_database2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.2.1", "my_database2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.1.1", "my_database2", "cmy2", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    // add global priv
    auth.clear();
    grantGlobalPrivs("%", "cmy", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.SELECT_PRIV));
    grantDbPrivs("192.168.1.%", "database", "cmy", false, false, false, PrivBitSet.of(PaloPrivilege.ALTER_PRIV));
    Assert.assertTrue(auth.checkDbPriv("192.168.1.1", "database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV, PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkDbPriv("192.168.1.1", "database2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.2.1", "database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.1.1", "database2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    // test persist
    auth = testPersist(auth);
    Assert.assertTrue(auth.checkDbPriv("192.168.1.1", "database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV, PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkDbPriv("192.168.1.1", "database2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.2.1", "database", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkDbPriv("192.168.1.1", "database2", "cmy", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
}

@Test
public void testTblPriv() throws DdlException, IllegalAccessException, IllegalArgumentException, InvocationTargetException {
    // normal
    grantTblPrivs("192.%.1.1", "db\\_%", "cmy%", "tbl%", false, false, false, PrivBitSet.of(PaloPrivilege.SELECT_PRIV, PaloPrivilege.LOAD_PRIV));
    Assert.assertTrue(auth.checkTblPriv("192.168.1.1", "db_1", "cmy", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.LOAD_PRIV, PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkTblPriv("192.168.1.1", "db_1", "cmy", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    // add db priv
    grantDbPrivs("192.%", "db\\_123", "cmy", false, false, false, PrivBitSet.of(PaloPrivilege.ALTER_PRIV));
    Assert.assertTrue(auth.checkTblPriv("192.168.1.1", "db_123", "cmy", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkTblPriv("192.168.1.1", "db_123", "cmy", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.SELECT_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkTblPriv("10.168.1.1", "db_123", "cmy", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.ALTER_PRIV), Operator.OR)));
    // add global priv
    grantGlobalPrivs("192.168.2.1", "cmy\\_admin", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.DROP_PRIV));
    Assert.assertTrue(auth.checkTblPriv("192.168.2.1", "db_123", "cmy_admin", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.DROP_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkTblPriv("192.168.1.1", "db_123", "cmy_admin", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.DROP_PRIV), Operator.OR)));
    // test persist
    auth = testPersist(auth);
    Assert.assertTrue(auth.checkTblPriv("192.168.2.1", "db_123", "cmy_admin", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.DROP_PRIV), Operator.OR)));
    Assert.assertFalse(auth.checkTblPriv("192.168.1.1", "db_123", "cmy_admin", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.DROP_PRIV), Operator.OR)));
    // add global priv
    grantGlobalPrivs("%", "cmy2", passwd, false, false, false, PrivBitSet.of(PaloPrivilege.DROP_PRIV));
    Assert.assertTrue(auth.checkTblPriv("", "db_123", "cmy2", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.DROP_PRIV), Operator.OR)));
    Assert.assertTrue(auth.checkTblPriv(null, "db_123", "cmy2", "tbl", PrivPredicate.of(PrivBitSet.of(PaloPrivilege.DROP_PRIV), Operator.OR)));
}

