    Assert.assertEquals(TTaskType.CANCEL_DELETE, request9.getTask_type());
    Assert.assertEquals(cancelDeleteTask.getSignature(), request9.getSignature());
    Assert.assertNotNull(request9.getCancel_delete_data_req());
}

